package com.itmeansbigmountain.whosgrindingclanpanel;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class SocialTrackingServiceTest
{
	private final Clock fixedClock = Clock.fixed(Instant.parse("2026-07-05T12:00:00Z"), ZoneOffset.UTC);

	@Test
	public void rescanMergesSameMemberAcrossSources()
	{
		SocialTrackingService service = new SocialTrackingService(fixedClock);

		service.rescan(Arrays.asList(
			SocialSourceSnapshot.members(TrackedMemberSource.FRIEND, Collections.singletonList(" Oyama ")),
			SocialSourceSnapshot.members(TrackedMemberSource.CLAN, Collections.singletonList("Oyama"))
		), 10);

		SocialTrackerState state = service.snapshot(10);
		assertEquals(1, state.members().size());
		assertTrue(state.members().get(0).hasSource(TrackedMemberSource.FRIEND));
		assertTrue(state.members().get(0).hasSource(TrackedMemberSource.CLAN));
	}

	@Test
	public void removeMemberIgnoresFutureScans()
	{
		SocialTrackingService service = new SocialTrackingService(fixedClock);
		service.rescan(Collections.singletonList(
			SocialSourceSnapshot.members(TrackedMemberSource.FRIEND, Collections.singletonList("Skiller Alt"))
		), 10);

		assertTrue(service.removeMember("skiller alt"));
		service.rescan(Collections.singletonList(
			SocialSourceSnapshot.members(TrackedMemberSource.FRIEND, Collections.singletonList("Skiller Alt"))
		), 10);

		assertEquals(0, service.snapshot(10).members().size());
		assertEquals(1, service.snapshot(10).ignoredCount());
		assertFalse(service.serializeIgnoredMembers().isEmpty());
	}

	@Test
	public void maxTrackedMembersCapsNewEntries()
	{
		SocialTrackingService service = new SocialTrackingService(fixedClock);
		service.rescan(Collections.singletonList(
			SocialSourceSnapshot.members(TrackedMemberSource.CLAN, Arrays.asList("One", "Two", "Three"))
		), 2);

		assertEquals(2, service.snapshot(2).members().size());
	}

	@Test
	public void removeOfflineFriendsDropsPreviouslyShownOfflineRows()
	{
		SocialTrackingService service = new SocialTrackingService(fixedClock);
		service.rescan(Collections.singletonList(
			SocialSourceSnapshot.observedMembers(TrackedMemberSource.FRIEND, Arrays.asList(
				SocialMemberSnapshot.of("Online Pal", 415, "Friend • world 415"),
				SocialMemberSnapshot.of("Offline Pal", -1, "Friend • offline")
			))
		), 10);

		assertEquals(2, service.snapshot(10).members().size());

		service.removeOfflineFriends();

		SocialTrackerState state = service.snapshot(10);
		assertEquals(1, state.members().size());
		assertEquals("Online Pal", state.members().get(0).displayName());
	}

	@Test
	public void defaultSourceSnapshotsDoNotSeedFakeMembers()
	{
		SocialTrackingService service = new SocialTrackingService(fixedClock);

		service.rescan(SocialTrackingService.seedSnapshots(true, true, true), 100);

		SocialTrackerState state = service.snapshot(100);
		assertEquals(0, state.members().size());
		assertEquals(3, state.messages().size());
	}
}

package com.itmeansbigmountain.whosgrindingclanpanel;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class WiseOldManGainedClientTest
{
	@Test
	public void summarizesAllPeriodGainsAcrossSkillsBossesAndActivities()
	{
		String json = "{\"data\":{" 
			+ "\"skills\":{"
			+ "\"overall\":{\"experience\":{\"gained\":999999}},"
			+ "\"ranged\":{\"experience\":{\"gained\":420000}},"
			+ "\"slayer\":{\"experience\":{\"gained\":180000}},"
			+ "\"strength\":{\"experience\":{\"gained\":2}},"
			+ "\"attack\":{\"experience\":{\"gained\":1}},"
			+ "\"fishing\":{\"experience\":{\"gained\":1500}}"
			+ "},"
			+ "\"bosses\":{\"chambers_of_xeric\":{\"kills\":{\"gained\":70}},\"tombs_of_amascut\":{\"kills\":{\"gained\":55}},\"theatre_of_blood\":{\"kills\":{\"gained\":40}},\"zulrah\":{\"kills\":{\"gained\":12}}},"
			+ "\"activities\":{\"clue_scrolls_hard\":{\"score\":{\"gained\":3}},\"last_man_standing\":{\"score\":{\"gained\":34}},\"bounty_hunter_hunter\":{\"score\":{\"gained\":2}},\"soul_wars\":{\"score\":{\"gained\":20}}}"
			+ "}}";

		String summary = WiseOldManGainedClient.summarizeGains(json);

		assertTrue(summary.contains("<b>Skills</b>:<br>▴ Ranged: <b>+420,000 xp</b><br>▴ Slayer: <b>+180,000 xp</b>"));
		assertTrue(summary.contains("Ranged: <b>+420,000 xp</b>"));
		assertTrue(summary.contains("Slayer: <b>+180,000 xp</b>"));
		assertTrue(summary.contains("Fishing: <b>+1,500 xp</b>"));
		assertTrue(summary.contains("Strength: <b>+2 xp</b>"));
		assertTrue(summary.contains("Attack: <b>+1 xp</b>"));
		assertTrue(summary.contains("CoX: <b>+70 kc</b>"));
		assertTrue(summary.contains("ToA: <b>+55 kc</b>"));
		assertTrue(summary.contains("ToB: <b>+40 kc</b>"));
		assertTrue(summary.contains("Zulrah: <b>+12 kc</b>"));
		assertTrue(summary.contains("<b>Bosses</b>:<br>⚔ CoX: <b>+70 kc</b><br>⚔ ToA: <b>+55 kc</b><br>⚔ ToB: <b>+40 kc</b>"));
		assertTrue(summary.contains("<b>Activities</b>:<br>★ LMS: <b>+34 score</b><br>★ SW: <b>+20 score</b><br>★ Clue Scrolls Hard: <b>+3 score</b>"));
		assertTrue(summary.contains("Bounty Hunter: <b>+2 score</b>"));
	}

	@Test
	public void reportsNoGainsWhenAllTrackedValuesAreZero()
	{
		String json = "{\"data\":{\"skills\":{\"ranged\":{\"experience\":{\"gained\":0}}},\"bosses\":{},\"activities\":{}}}";

		assertEquals("No recent gains<br>found. WOM tracking<br>was started/updated if<br>needed. Try 30/365<br>days or check<br>again after XP/KC<br>changes.", WiseOldManGainedClient.summarizeGains(json));
	}
}

