	}

	String summary()
	{
		return summary;
	}
}

package com.itmeansbigmountain.whosgrindingclanpanel;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Friend;
import net.runelite.api.FriendContainer;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = WhosGrindingClanPanelPlugin.PLUGIN_NAME,
	description = "Shows compact WOM gains for friends, friends chat, and clan members.",
	tags = {"friends", "grind", "activity", "skills", "xp"}
)
public class WhosGrindingClanPanelPlugin extends Plugin
{
	static final String PLUGIN_NAME = "Who's Grinding Panel";
	static final String CONFIG_GROUP = "whosgrindingclanpanel";
	static final int DEFAULT_ACTIVITY_WINDOW_MINUTES = 30;
	static final int DEFAULT_MAX_PLAYERS_SHOWN = 8;
	static final int MIN_ACTIVITY_WINDOW_MINUTES = 5;
	static final int MAX_ACTIVITY_WINDOW_MINUTES = 240;
	static final int MIN_PLAYERS_SHOWN = 1;
	static final int MAX_PLAYERS_SHOWN = 25;
	@Inject
	private Client client;

	@Inject
	private WhosGrindingClanPanelConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OkHttpClient httpClient;

	private WhosGrindingClanPanelPanel panel;
	private NavigationButton navButton;
	private SocialTrackingService trackingService;
	private Instant lastAutomaticRefresh;

	@Override
	protected void startUp()
	{
		trackingService = new SocialTrackingService();
		trackingService.loadIgnoredMembers(config.ignoredMembers());
		rescanSocialSources("startup");

		panel = new WhosGrindingClanPanelPanel(config, trackingService.snapshot(config.maxTrackedMembers()), new WhosGrindingClanPanelPanel.PanelActions()
		{
			@Override
			public void refreshRequested()
			{
				rescanSocialSources("manual refresh");
				refreshPanel();
			}

			@Override
			public void gainsPeriodChanged(GainsPeriod gainsPeriod)
			{
				configManager.setConfiguration(CONFIG_GROUP, "gainsPeriod", gainsPeriod);
				refreshPanel();
			}

			@Override
			public void showOfflineFriendsChanged(boolean showOfflineFriends)
			{
				configManager.setConfiguration(CONFIG_GROUP, "showOfflineFriends", showOfflineFriends);
				if (!showOfflineFriends)
				{
					trackingService.removeOfflineFriends();
					refreshPanel();
					return;
				}
				rescanSocialSources("show offline friends changed");
				refreshPanel();
			}
		}, httpClient);
		navButton = NavigationButton.builder()
			.tooltip(PLUGIN_NAME)
			.icon(buildNavigationIcon())
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		log.debug("{} started", PLUGIN_NAME);
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
		trackingService = null;
		lastAutomaticRefresh = null;
		log.debug("{} stopped", PLUGIN_NAME);
	}

	private static BufferedImage buildNavigationIcon()
	{
		try (InputStream stream = WhosGrindingClanPanelPlugin.class.getResourceAsStream("/whos_grinding_icon.png"))
		{
			if (stream != null)
			{
				return ImageIO.read(stream);
			}
		}
		catch (IOException ignored)
		{
			// Use RuneLite's blank fallback if icon decoding fails.
		}
		return new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN && trackingService != null)
		{
			rescanSocialSources("login");
			refreshPanel();
		}

		if (gameStateChanged.getGameState() != GameState.LOGGED_IN || !config.showLoginHint())
		{
			return;
		}

		client.addChatMessage(
			ChatMessageType.GAMEMESSAGE,
			"",
			buildLoginHint(config.activityWindowMinutes(), config.maxPlayersShown()),
			null
		);
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		if (client.getGameState() != GameState.LOGGED_IN || trackingService == null)
		{
			return;
		}

		Instant now = Instant.now();
		int refreshMinutes = Math.max(1, config.refreshIntervalMinutes());
		if (lastAutomaticRefresh == null || Duration.between(lastAutomaticRefresh, now).toMinutes() >= refreshMinutes)
		{
			rescanSocialSources("scheduled " + refreshMinutes + " minute refresh");
			refreshPanel();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!CONFIG_GROUP.equals(configChanged.getGroup()) || trackingService == null)
		{
			return;
		}
		trackingService.loadIgnoredMembers(config.ignoredMembers());
		rescanSocialSources("config change");
		refreshPanel();
	}

	private void rescanSocialSources(String reason)
	{
		updateCurrentPlayerName();
		trackingService.rescan(
			buildSocialSnapshots(),
			config.maxTrackedMembers()
		);
		if (!config.showOfflineFriends())
		{
			trackingService.removeOfflineFriends();
		}
		lastAutomaticRefresh = Instant.now();
		log.debug("{} rescanned social sources: {}", PLUGIN_NAME, reason);
	}

	private void updateCurrentPlayerName()
	{
		if (trackingService == null)
		{
			return;
		}
		Player localPlayer = client.getLocalPlayer();
		trackingService.setCurrentPlayerName(localPlayer == null ? null : localPlayer.getName());
	}

	private List<SocialSourceSnapshot> buildSocialSnapshots()
	{
		List<SocialSourceSnapshot> snapshots = new ArrayList<>();
		if (config.trackFriendsList())
		{
			snapshots.add(scanFriendsList());
		}
		if (config.trackFriendsChat())
		{
			snapshots.add(scanFriendsChat());
		}
		if (config.trackClanChat())
		{
			snapshots.add(scanClanChat());
		}
		if (snapshots.isEmpty())
		{
			snapshots.add(SocialSourceSnapshot.unsupported(TrackedMemberSource.FRIEND, "All tracking sources are disabled in config."));
		}
		return snapshots;
	}

	private SocialSourceSnapshot scanFriendsList()
	{
		FriendContainer friendContainer = client.getFriendContainer();
		if (friendContainer == null || friendContainer.getMembers() == null)
		{
			return SocialSourceSnapshot.unsupported(TrackedMemberSource.FRIEND, "Friends list is not available yet.");
		}

		List<SocialMemberSnapshot> members = new ArrayList<>();
		for (Friend friend : friendContainer.getMembers())
		{
			if (friend != null && (config.showOfflineFriends() || friend.getWorld() > 0))
			{
				members.add(SocialMemberSnapshot.of(friend.getName(), friend.getWorld(), sourceSummary("Friend", friend.getWorld())));
			}
		}
		return SocialSourceSnapshot.observedMembers(TrackedMemberSource.FRIEND, members);
	}

	private SocialSourceSnapshot scanFriendsChat()
	{
		FriendsChatManager friendsChatManager = client.getFriendsChatManager();
		if (friendsChatManager == null || friendsChatManager.getMembers() == null)
		{
			return SocialSourceSnapshot.unsupported(TrackedMemberSource.FRIENDS_CHAT, "Friends chat is not available yet.");
		}

		List<SocialMemberSnapshot> members = new ArrayList<>();
		for (FriendsChatMember friendsChatMember : friendsChatManager.getMembers())
		{
			if (friendsChatMember != null)
			{
				members.add(SocialMemberSnapshot.of(friendsChatMember.getName(), friendsChatMember.getWorld(), sourceSummary("Friends chat", friendsChatMember.getWorld())));
			}
		}
		return SocialSourceSnapshot.observedMembers(TrackedMemberSource.FRIENDS_CHAT, members);
	}

	private SocialSourceSnapshot scanClanChat()
	{
		ClanChannel clanChannel = client.getClanChannel();
		if (clanChannel == null || clanChannel.getMembers() == null)
		{
			return SocialSourceSnapshot.unsupported(TrackedMemberSource.CLAN, "Clan chat is not available yet.");
		}

		List<SocialMemberSnapshot> members = new ArrayList<>();
		for (ClanChannelMember clanMember : clanChannel.getMembers())
		{
			if (clanMember != null)
			{
				members.add(SocialMemberSnapshot.of(clanMember.getName(), clanMember.getWorld(), sourceSummary("Clan chat", clanMember.getWorld())));
			}
		}
		return SocialSourceSnapshot.observedMembers(TrackedMemberSource.CLAN, members);
	}

	private String sourceSummary(String sourceName, int world)
	{
		return world > 0 ? sourceName + " • world " + world : sourceName + " • offline";
	}

	private void refreshPanel()
	{
		if (panel != null)
		{
			panel.setState(trackingService.snapshot(config.maxTrackedMembers()));
		}
	}

	static String buildLoginHint(int activityWindowMinutes, int maxPlayersShown)
	{
		int safeWindow = clamp(
			activityWindowMinutes,
			MIN_ACTIVITY_WINDOW_MINUTES,
			MAX_ACTIVITY_WINDOW_MINUTES,
			DEFAULT_ACTIVITY_WINDOW_MINUTES
		);
		int safeMaxPlayers = clamp(
			maxPlayersShown,
			MIN_PLAYERS_SHOWN,
			MAX_PLAYERS_SHOWN,
			DEFAULT_MAX_PLAYERS_SHOWN
		);

		return PLUGIN_NAME + " is ready. It is tracking up to "
			+ safeMaxPlayers
			+ " visible rows from your friends and friends chat sources over a "
			+ safeWindow
			+ " minute activity window.";
	}

	static String formatActivityLine(String playerName, String activityLabel, long gainedXp)
	{
		String safeName = normalizePlayerName(playerName);
		String safeActivity = normalizeActivityLabel(activityLabel);
		long safeXp = Math.max(0, gainedXp);

		return safeName + " - " + safeActivity + " (" + safeXp + " xp gained)";
	}

	static String normalizePlayerName(String playerName)
	{
		if (playerName == null || playerName.trim().isEmpty())
		{
			return "Unknown player";
		}

		return playerName
			.replace('\u00A0', ' ')
			.trim()
			.replaceAll("\\s+", " ");
	}

	private static String normalizeActivityLabel(String activityLabel)
	{
		if (activityLabel == null || activityLabel.trim().isEmpty())
		{
			return "training";
		}

		return activityLabel.trim().replaceAll("\\s+", " ");
	}

	private static int clamp(int value, int min, int max, int fallback)
	{
		if (value < min || value > max)
		{
			return fallback;
		}

		return value;
	}

	@Provides
	WhosGrindingClanPanelConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WhosGrindingClanPanelConfig.class);
	}
}

package com.itmeansbigmountain.whosgrindingclanpanel;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

final class WiseOldManGainedClient implements GrindingSummaryClient
{
	private static final String API_BASE_URL = "https://api.wiseoldman.net/v2/players/";
	private static final MediaType JSON = MediaType.parse("application/json");
	private final OkHttpClient httpClient;

	WiseOldManGainedClient(OkHttpClient httpClient)
	{
		this.httpClient = httpClient;
	}

	@Override
	public String fetchGrindingSummary(String playerName, GainsPeriod period) throws IOException
	{
		String normalizedName = WhosGrindingClanPanelPlugin.normalizePlayerName(playerName);
		GainsPeriod safePeriod = period == null ? GainsPeriod.SEVEN_DAYS : period;
		HttpResult gainedResult = request("GET", gainedUrl(normalizedName, safePeriod));
		if (gainedResult.responseCode != 200 || (gainedResult.responseCode == 200 && summarizeGains(gainedResult.body).startsWith("No recent gains")))
		{
			// If the player is not tracked yet, or has stale/no gains, ask WOM to create/update then retry gained.
			HttpResult updateResult = request("POST", API_BASE_URL + PlayerTrackingLinks.urlEncode(normalizedName));
			if (updateResult.responseCode != 200 && updateResult.responseCode != 201)
			{
				return "Player not on<br>WOM yet. Saved<br>official baseline<br>and will keep<br>checking trackers.";
			}
			gainedResult = request("GET", gainedUrl(normalizedName, safePeriod));
		}
		if (gainedResult.responseCode != 200)
		{
			throw new IOException("Wise Old Man gained returned HTTP " + gainedResult.responseCode);
		}
		return summarizeGains(gainedResult.body);
	}

	private static String gainedUrl(String normalizedName, GainsPeriod period)
	{
		return API_BASE_URL + PlayerTrackingLinks.urlEncode(normalizedName) + "/gained?period=" + period.wiseOldManPeriod();
	}

	private HttpResult request(String method, String url) throws IOException
	{
		Request.Builder request = new Request.Builder()
			.url(url)
			.header("User-Agent", "WhosGrindingPanel RuneLite plugin")
			.header("Accept", "application/json");
		if ("POST".equals(method))
		{
			request.post(RequestBody.create(JSON, new byte[0]));
		}
		try (Response response = httpClient.newCall(request.build()).execute())
		{
			String body = response.body() == null ? "" : response.body().string();
			return new HttpResult(response.code(), body);
		}
	}

	static String summarizeGains(String json)
	{
		JsonObject root = new JsonParser().parse(json).getAsJsonObject();
		JsonObject data = root.getAsJsonObject("data");
		if (data == null)
		{
			return "No recent gains<br>found. WOM tracking<br>was started/updated if<br>needed. Try 30/365<br>days or check<br>again after XP/KC<br>changes.";
		}

		List<GainedLine> skills = new ArrayList<>();
		List<GainedLine> bosses = new ArrayList<>();
		List<GainedLine> activities = new ArrayList<>();
		collectSection(skills, data.getAsJsonObject("skills"), "XP", "experience", "xp", true);
		collectSection(bosses, data.getAsJsonObject("bosses"), "KC", "kills", "kc", false);
		collectSection(activities, data.getAsJsonObject("activities"), "Score", "score", "score", false);

		List<String> sections = new ArrayList<>();
		addSection(sections, "Skills", skills);
		addSection(sections, "Bosses", bosses);
		addSection(sections, "Activities", activities);

		if (sections.isEmpty())
		{
			return "No recent gains<br>found. WOM tracking<br>was started/updated if<br>needed. Try 30/365<br>days or check<br>again after XP/KC<br>changes.";
		}
		return String.join("<br>", sections);
	}

	private static void addSection(List<String> sections, String title, List<GainedLine> lines)
	{
		List<GainedLine> positiveLines = lines.stream()
			.filter(line -> line.gained > 0)
			.sorted(Comparator.comparingLong((GainedLine line) -> line.gained).reversed())
			.collect(Collectors.toList());
		if (!positiveLines.isEmpty())
		{
			boolean onePerLine = true;
			String separator = onePerLine ? "<br>" : "; ";
			String headingSeparator = onePerLine ? ":<br>" : ": ";
			sections.add("<b>" + title + "</b>" + headingSeparator
				+ positiveLines.stream().map(GainedLine::format).collect(Collectors.joining(separator)));
		}
	}

	private static void collectSection(List<GainedLine> lines, JsonObject section, String label, String valueObject, String suffix, boolean skipOverall)
	{
		if (section == null)
		{
			return;
		}
		for (String metric : section.keySet())
		{
			if (skipOverall && "overall".equals(metric))
			{
				continue;
			}
			JsonObject metricObject = section.getAsJsonObject(metric);
			JsonObject gainedObject = metricObject == null ? null : metricObject.getAsJsonObject(valueObject);
			long gained = gainedLong(gainedObject);
			if (gained > 0)
			{
				lines.add(new GainedLine(prettyMetric(metric), label, gained, suffix));
			}
		}
	}

	private static long gainedLong(JsonObject object)
	{
		if (object == null)
		{
			return 0;
		}
		JsonElement gained = object.get("gained");
		return gained == null || gained.isJsonNull() ? 0 : Math.max(0, gained.getAsLong());
	}

	private static String prettyMetric(String metric)
	{
		switch (metric)
		{
			case "chambers_of_xeric":
				return "CoX";
			case "chambers_of_xeric_challenge_mode":
				return "CM CoX";
			case "theatre_of_blood":
				return "ToB";
			case "theatre_of_blood_hard_mode":
				return "HMT";
			case "tombs_of_amascut":
				return "ToA";
			case "tombs_of_amascut_expert":
				return "ToA Expert";
			case "corrupted_gauntlet":
				return "CG";
			case "general_graardor":
				return "Bandos";
			case "commander_zilyana":
				return "Zily";
			case "kril_tsutsaroth":
				return "Zammy";
			case "kreearra":
				return "Arma";
			case "dagannoth_rex":
				return "Rex";
			case "dagannoth_prime":
				return "Prime";
			case "dagannoth_supreme":
				return "Supreme";
			case "kalphite_queen":
				return "KQ";
			case "king_black_dragon":
				return "KBD";
			case "corporeal_beast":
				return "Corp";
			case "cerberus":
				return "Cerb";
			case "grotesque_guardians":
				return "GG";
			case "phosanis_nightmare":
				return "PNM";
			case "the_nightmare":
				return "NM";
			case "phantom_muspah":
				return "Muspah";
			case "thermonuclear_smoke_devil":
				return "Thermy";
			case "wintertodt":
				return "WT";
			case "tzkal_zuk":
				return "Zuk";
			case "tztok_jad":
				return "Jad";
			case "vardorvis":
				return "Vard";
			case "the_leviathan":
				return "Levi";
			case "the_whisperer":
				return "Whisp";
			case "venenatis":
				return "Vene";
			case "sarachnis":
				return "Sarach";
			case "zalcano":
				return "Zalc";
			case "last_man_standing":
				return "LMS";
			case "bounty_hunter_hunter":
				return "Bounty Hunter";
			case "bounty_hunter_rogue":
				return "Bounty Hunter Rogue";
			case "soul_wars":
				return "SW";
			case "pest_control":
				return "PC";
			case "barbarian_assault":
				return "BA";
			case "castle_wars":
				return "CW";
			case "guardians_of_the_rift":
				return "GotR";
			case "volcanic_mine":
				return "VM";
			case "collection_log":
				return "Col Log";
			default:
				break;
		}
		String[] words = metric.replace('_', ' ').split(" ");
		StringBuilder label = new StringBuilder();
		for (String word : words)
		{
			if (word.isEmpty())
			{
				continue;
			}
			if (label.length() > 0)
			{
				label.append(' ');
			}
			label.append(word.substring(0, 1).toUpperCase(Locale.ROOT)).append(word.substring(1));
		}
		return label.toString();
	}

	private static String formatNumber(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}

	private static final class HttpResult
	{
		private final int responseCode;
		private final String body;

		private HttpResult(int responseCode, String body)
		{
			this.responseCode = responseCode;
			this.body = body;
		}
	}

	private static final class GainedLine
	{
		private final String metric;
		private final String label;
		private final long gained;
		private final String suffix;

		private GainedLine(String metric, String label, long gained, String suffix)
		{
			this.metric = metric;
			this.label = label;
			this.gained = gained;
			this.suffix = suffix;
		}

		private String format()
		{
			return icon() + " " + metric + ": <b>+" + formatNumber(gained) + " " + suffix + "</b>";
		}

		private String icon()
		{
			if ("XP".equals(label))
			{
				return "▴";
			}
			if ("KC".equals(label))
			{
				return "⚔";
			}
			return "★";
		}
	}
}

package com.itmeansbigmountain.whosgrindingclanpanel;

public enum GainsPeriod
{
	DAY("Day", 1, "day"),
	SEVEN_DAYS("7 days", 7, "week"),
	THIRTY_DAYS("30 days", 30, "month"),
	YEAR("365 days", 365, "year");

	private final String label;
	private final int days;
	private final String wiseOldManPeriod;

	GainsPeriod(String label, int days, String wiseOldManPeriod)
	{
		this.label = label;
